FXM(qfold, """
public static java.util.UUID uuidOf(Object o) {
  if (o instanceof java.util.UUID) return (java.util.UUID) o;
  if (o instanceof String) { try { return java.util.UUID.fromString(((String) o).trim()); } catch (Throwable t) { return null; } }
  return null;
}""")
FXM(qfold, """
public static Object act(java.util.UUID u, String op) {
  @PKG@.SkyyHudPlugin p = @PKG@.Feed.PLUGIN;
  if (u == null || op == null || p == null) return Boolean.FALSE;
  String o = op.trim().toLowerCase(java.util.Locale.ROOT);
  java.util.Map m = @PKG@.LayoutStore.get(u);
  @PKG@.WLayout l = (@PKG@.WLayout) m.get("Quest");
  if (l == null) return Boolean.FALSE;
  if (o.equals("state")) return !l.en ? "hidden" : (l.opt ? "open" : "folded");
  boolean have = @PKG@.Widgets.questHave(@PKG@.Widgets.bridge());
  // fix pass: toggle / fold need a tracker that draws something - no quest showing = FALSE, nothing saved (the caller opens the Menu)
  if ((o.equals("toggle") || o.equals("fold")) && have && !@PKG@.Widgets.shown(@PKG@.Widgets.questModelU(u))) return Boolean.FALSE;
  if (o.equals("toggle")) {
    if (!have || !l.en) return Boolean.FALSE;   // fix pass 2: never re-enable a tracker the player switched off (the caller opens the Menu)
    l.opt = !l.opt;
  } else if (o.equals("fold")) {
    if (!have) return Boolean.FALSE;
    l.en = true;
    l.opt = false;
  } else if (o.equals("open")) { l.en = true; l.opt = true; }
  else if (o.equals("hide")) l.en = false;
  else if (o.equals("show")) { l.en = true; l.opt = true; }
  else return Boolean.FALSE;
  l.optH = false;
  @PKG@.Widgets.clampToScreen(l);
  @PKG@.LayoutStore.save(u);
  Object h = p.huds.get(u);
  if (h != null) ((@PKG@.HudMain) h).rebuild();
  return Boolean.TRUE;
}""")
FXM(qfold, """
public Object apply(Object o) {
  try {
    CALLS.incrementAndGet();
    if (!(o instanceof Object[])) return Boolean.FALSE;
    Object[] a = (Object[]) o;
    if (a.length < 2 || !(a[1] instanceof String)) return Boolean.FALSE;
    return act(uuidOf(a[0]), (String) a[1]);
  } catch (Throwable t) { return Boolean.FALSE; }
}""")

